                                                                                                                                                                                                                
  CREATE TABLE "FMP_USER_ROLE"                                                                                                                                                                        
   (	"USER_ROLE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"USER_ID" NUMBER(20,0),                                                                                                                                                                                        
	"ROLE_ID" NUMBER(20,0),                                                                                                                                                                                        
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                      
	"REMARK" VARCHAR2(500),                                                                                                                                                                                        
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                          
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                            
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                              
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                             
	"USER_ROLE_TYPE" VARCHAR2(128),                                                                                                                                                                                
	 PRIMARY KEY ("USER_ROLE_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                           
   ) ;                                                                                                                                                                                                          


